def write_page(path,title,desc,body,kind='WebPage',extra=None,crumbs=None):
 PAGES.append(dict(path=path,title=title,description=desc))
 schemas=[{'@context':'https://schema.org','@type':kind,'@id':url(path)+'#page','url':url(path),'name':title,'description':desc,'isPartOf':{'@id':ORIGIN+'/#website'}}]
 if path=='/':schemas.append({'@context':'https://schema.org','@type':'WebSite','@id':ORIGIN+'/#website','name':'Helmies','url':ORIGIN})
 if extra:schemas.append({'@context':'https://schema.org',**extra})
 if crumbs:schemas.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':url(p)} for i,(n,p) in enumerate([('Home','/')]+crumbs)]})
