 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="helmies-page" content="v2"><title>{e(title)} | Helmies</title><meta name="description" content="{e(desc,quote=True)}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#0b081a"><meta property="og:type" content="website"><meta property="og:title" content="{e(title,quote=True)} | Helmies"><meta property="og:description" content="{e(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://www.helmies.fi/assets/images/og-image.webp"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="https://www.helmies.fi/assets/images/og-image.webp"><link rel="icon" href="/assets/icon-transparent-192.png" type="image/png"><link rel="apple-touch-icon" href="/assets/icon-transparent-180.png"><link rel="manifest" href="/manifest.webmanifest"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/cinema.css?v=7"><link rel="stylesheet" href="/content.css?v=10"><script src="/app.js?v=10" defer></script><script src="/content.js?v=10" defer></script><script src="/navigator.js" defer></script>{scene_script}<script type="application/ld+json">{json.dumps(schemas,ensure_ascii=False).replace('</','<\\/')}</script></head><body id="top" data-page="{path}">{header}<main id="main">{body}</main>{footer}{brief}{search}{navigator}</body></html>'''
