 body=breadcrumb([('Services','/services/'),(s['name'],None)])+introhero(f'{i+1:02} / {s["name"].upper()}',title,s['desc'],'ribbons' if s['group'] in ['Creative','Growth'] else 'logo-3d')
 body+=f'<section class="section service-overview"><div><p class="eyebrow">{s["group"].upper()} / HELMIES</p><h2>{s["short"]}</h2><p class="body-large">{s["intro"]}</p><button class="button primary" data-service="{e(s["name"],quote=True)}">Let’s talk about {"your project" if len(s["name"])>18 else s["name"].lower()}<span class="button-bead"></span></button></div><aside class="deliverables"><span class="eyebrow">WHAT WE CAN CREATE</span><ul>'+''.join(f'<li><span>0{j+1}</span>{o}</li>' for j,o in enumerate(s['outputs']))+'</ul></aside></section>'
 body+='<section class="section use-cases">'+label('BUILT AROUND YOUR WORLD','POSSIBLE STARTING POINTS')+'<h2>What could this<br><span class="soft-text">make possible?</span></h2><div class="three-grid">'+''.join(f'<article class="reveal"><span>0{j+1}</span><h3>{h}</h3><p>{p}</p></article>' for j,(h,p) in enumerate(s['uses']))+'</div></section>'
 body+='<section class="section detail-process"><div><p class="eyebrow">HOW WE GET THERE</p><h2>A clear path<br>to <span class="gradient-text">what’s next.</span></h2><a class="text-link" href="/approach/">Explore our approach</a></div><ol>'+''.join(f'<li><span>0{j+1}</span><p>{p}</p></li>' for j,p in enumerate(s['process']))+'</ol></section>'
