 body+='<section class="section content-readiness">'+label('MAKE THE FIRST CONVERSATION COUNT','YOUR STARTING POINT')+'<div class="three-grid"><article><h3>Bring the context.</h3><p>Tell us who the work is for, what is difficult today, and what a useful change would look like. Share relevant existing material so we can understand the starting point.</p></article><article><h3>Choose the first outcome.</h3><p>We can prioritize '+s['outputs'][0].lower()+' or another focused deliverable, then agree what belongs in this stage and what can follow.</p></article><article><h3>Plan for real use.</h3><p>Who will approve the work, keep it current, and use the handover? Clarifying those roles helps the result become part of your everyday business.</p></article></div></section>'
 reading=[a for a in ARTICLES if a['related']==s['slug']]
 if reading:body+='<section class="section">'+label('BEFORE YOU BEGIN','FROM THE JOURNAL')+articlecards(reading[:3])+'</section>'
