body=breadcrumb([('The studio',None)])+introhero('INDEPENDENT BY DESIGN','A curious mind.<br><span class="gradient-text">An open universe.</span>','Helmies connects design, development, and storytelling. We’re here for the ideas that don’t fit neatly into one discipline.','logo-3d')
body+='<section class="section studio-story"><div><p class="eyebrow">FOUNDED BY WAEL HELMI</p><h2>Design meets code.<br>Then things<br><span class="gradient-text">get interesting.</span></h2></div><div><p class="body-large">Helmies grew from a practice that moves between visual identity, digital products, automation, and creative production.</p><p>That range is useful. It means a visual idea can be considered alongside the system that supports it. A business problem can lead to an app, an automation, a clearer message—or a combination of all three.</p><p>Founded by Wael Helmi and based in Finland, the studio works remotely with clients and collaborators. Conversations can happen in English, Finnish, or Arabic.</p><div class="founder-line"><img src="/assets/helmies-mark.png" width="60" height="60" alt="Helmies logo"><div><strong>Wael Helmi</strong><span>FOUNDER · DESIGNER · DEVELOPER</span></div></div></div></section><section class="section values">'+label('WHAT GUIDES THE WORK','A FEW THINGS WE BELIEVE')+'<div class="three-grid"><article><span>01 / CURIOSITY</span><h3>Ask a better question.</h3><p>The first request is sometimes the start of the brief. We look for the underlying problem before choosing the medium or tool.</p></article><article><span>02 / CRAFT</span><h3>Care about the details.</h3><p>The rhythm of an edit, the clarity of a form, the recovery path in an automation. Small decisions shape the whole experience.</p></article><article><span>03 / INTENTION</span><h3>Use technology with purpose.</h3><p>AI and automation are useful when they serve a real need. We choose an approach around the project, not the trend.</p></article></div></section>'+cta()
body=body.replace(cta(),'<section class="section content-readiness">'+label('A FOUNDER-LED PRACTICE','ONE CONNECTED CONVERSATION')+'<div class="three-grid"><article><h3>Direct creative dialogue.</h3><p>Discuss the problem with the person connecting the design and technical decisions. Clear conversations help the idea stay coherent as it moves between disciplines.</p></article><article><h3>A team around the brief.</h3><p>Different projects need different skills. The scope defines responsibilities, collaborators where needed, review stages, and what you will receive.</p></article><article><h3>Knowledge that stays useful.</h3><p>Handover is part of the work. We agree on practical files, guidance, and ownership so your next step does not depend on remembering a presentation.</p></article></div><a class="text-link" href="/faq/">Questions about working together</a></section>'+cta())
write_page('/studio/','About the studio & Wael Helmi','Meet Helmies, a Finland-based creative technology studio founded by designer and developer Wael Helmi.',body,extra={'@type':'AboutPage','name':'About Helmies','about':{'@id':ORIGIN+'/#studio'}},crumbs=[('The studio','/studio/')])
